            ans_path = is_hamiltonian_path(reduced)
            if ans_cycle == ans_path:
                passed += 1
            else:
                print("FAIL", instance, "reduced", reduced, ans_cycle, ans_path)
                sys.exit(1)
    # random tests for n=5,6
